--- 刷新UI
---@param emoLv any
---@param ldEmoLv any
function UIFightTeamLineupBonusNode:Refresh(emoLv)
    -- 等级是否发生改变
    local emoLvChanged = checkInt(emoLv) ~= checkInt(self.emoLv)
    local lvChanged = emoLvChanged

    self.emoLv = emoLv

    -- 未解锁
    local locked = self.locked or false
    KTool.SetActive(self.ImgLockBg, locked)
    if locked then
        KTool.SetActive(self.TxtTitle, false)
        KTool.SetActive(self.TxtAttribute, false)
        KTool.SetActive(self.TxtNotActive, false)
        CfUtils.SetUISwitchImage(self.ImgIcon_Switch.gameObject, 1)
        return
    end

    -- 已解锁
    local showDetail = self.showDetail or false
    KTool.SetActive(self.TxtTitle, not showDetail)
    
    local emoActived = (emoLv > 0)
    KTool.SetActive(self.TxtAttribute, showDetail and emoActived)
    KTool.SetActive(self.TxtNotActive, showDetail and not emoActived)

    CfUtils.SetUISwitchImage(self.ImgIcon_Switch.gameObject, self:GetIconSwitchId(emoLv))

    if showDetail and emoActived then
        CfUtils.FillText(self.TxtAttribute, self:GetAttributeDetail(emoLv))
    end

    KTool.SetActive(self.UIFX_Triggle, (emoLv == 3))
    KTool.SetActive(self.UIFX_Triggle_Full, (emoLv == 3))

    -- 刷新爆点
    local refreshFx = self.refreshFX or false
    local state = self.Animation_Fx:get_Item(AnimationActiveFXRefresh)
    if isNotNull(state) and emoActived and refreshFx and lvChanged then
        state.time = state.length
        self.Animation_Fx:Sample()
        CfUtils.PlayAnimation(self.UIFX_Triggle.gameObject, AnimationActiveFXRefresh, true)
    end
end

