--- 使用关卡id刷新阵容
---@param questId any
function UIFightTeamLineupBonusNode:RefreshLineupBtQuest(questId, teamIndex)
    ---@type TeamComponent
    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local teamTab = teamComponent:GetTeamByQuestId(questId, teamIndex)
    self:RefreshLineup(teamTab)
