--- 刷新阵容
---@param cardsInfo any
function UIFightTeamLineupBonusNode:RefreshLineup(cardsInfo)
    -- print("[情绪共鸣] 阵容 ", table.dump(cardsInfo, nil, 3))
    local result = CardUtils.CalculateEmotion(cardsInfo)
    local emoLv = result.emotionBonusLevel
    self:Refresh(emoLv)
end

function UIFightTeamLineupBonusNode:GetPopupUIData()
    local emoLv = self.emoLv

    local data = {}

    local vos = CfUtils.GetCf(AutoIds.IdSetting6221, "LineupBonusVo", true)
    for i, vo in ipairs(vos) do
        if vo.status == 1 then
            local detail2 = vo.name
            detail2 = string.gsub(detail2, '&', '')
            table.insert(data, {
                id = i,
                detail1 = vo.desc,
                detail2 = detail2,
                active = false,
                type = 1,
            })
        end
    end

    if emoLv > 0 then
        data[emoLv].active = true
    end

    return data
end

return UIFightTeamLineupBonusNode